def upgrade_existing_reports(apps, schema_editor):
    """Keep every existing chat safety report and move it to the new statuses and categories."""
    import secrets

    AbuseReport = apps.get_model("core", "AbuseReport")
    status_map = {"PENDING": "SUBMITTED", "ACTION_TAKEN": "RESOLVED", "RESOLVED": "RESOLVED"}
    reason_map = {"FRAUD": "SCAM"}
    used = set(AbuseReport.objects.exclude(reference=None).values_list("reference", flat=True))
    for report in AbuseReport.objects.all():
        report.status = status_map.get(report.status, report.status)
        report.reason = reason_map.get(report.reason, report.reason)
        if report.reviewed_by_id and not report.reviewed_at:
            report.reviewed_at = report.resolved_at
        if not report.reference:
            while True:
                reference = f"CSR-{report.created_at:%Y%m%d}-{secrets.token_hex(3).upper()}"
                if reference not in used:
                    used.add(reference)
                    break
            report.reference = reference
        report.save(update_fields=["status", "reason", "reviewed_at", "reference"])


def downgrade_reports(apps, schema_editor):
    AbuseReport = apps.get_model("core", "AbuseReport")
    for report in AbuseReport.objects.all():
        report.status = "PENDING" if report.status in {"SUBMITTED", "UNDER_REVIEW"} else "RESOLVED"
        report.reason = {"SCAM": "FRAUD", "INAPPROPRIATE": "OTHER"}.get(report.reason, report.reason)
        report.save(update_fields=["status", "reason"])


